const fn = new Function(code + "\nreturn { safeParse };");
const { safeParse } = fn();
const parsed = safeParse('{"a":1}', null);
if (!parsed || parsed.a !== 1) throw new Error("safeParse should parse that JSON text into an object whose a property is 1.");
if (safeParse("[1,2]", null)?.length !== 2) throw new Error("safeParse should parse arrays too.");
if (safeParse("42", 0) !== 42) throw new Error("A JSON number string parses to the number 42.");

const fn = new Function(code + "\nreturn { safeParse };");
const { safeParse } = fn();
if (safeParse("{nope", "x") !== "x") throw new Error("Invalid JSON must return the fallback, not throw.");
if (safeParse("", null) !== null) throw new Error("An empty string is not valid JSON — return the fallback.");

const fn = new Function(code + "\nreturn { safeParse };");
const { safeParse } = fn();
for (const bad of [undefined, null, {}, 123]) {
  let threw = false;
  try { safeParse(bad, "fb"); } catch { threw = true; }
  if (threw) throw new Error("safeParse must not throw even when json is not a string at all (got: " + typeof bad + ").");
}
